UPDATE account_recovery_tokens
SET used_at = #{invalidatedAt}
WHERE user_id = #{userId}
  AND used_at IS NULL

mapper.select:
SELECT MAX(created_at)
FROM account_recovery_tokens
WHERE user_id = #{userId}

SELECT id, user_id, expires_at, used_at, created_at
FROM account_recovery_tokens
WHERE token_hash = #{tokenHash}
  AND used_at IS NULL
  AND expires_at > #{currentTime}

mapper.update:
UPDATE account_recovery_tokens
SET used_at = #{usedAt}
WHERE id = #{id}
  AND used_at IS NULL
